  9→#[test]
 10→fn public_api_is_accessible() {
 11→    // Verify types are exported correctly
 12→    let _config = BivvyConfig::default();
 13→    let _ctx = InterpolationContext::new();
 14→    let _mode = OutputMode::Verbose;
 15→}
