 97→#[test]
 98→fn interpolation_context_workflow() {
 99→    let ctx = InterpolationContext::new()
100→        .with_project("myapp", std::path::Path::new("/projects/myapp"))
101→        .with_env(std::collections::HashMap::from([(
102→            "RAILS_ENV".to_string(),
103→            "development".to_string(),
104→        )]));
105→
106→    // Resolve with builtins
107→    let result = resolve_string("Project: ${project_name}", &ctx).unwrap();
108→    assert_eq!(result, "Project: myapp");
109→
110→    // Resolve with env
111→    let result = resolve_string("Environment: ${RAILS_ENV}", &ctx).unwrap();
112→    assert_eq!(result, "Environment: development");
113→}
