  1→//! Integration tests for the steps public API.
  2→
  3→use bivvy::config::{CompletedCheck, InterpolationContext, StepConfig};
  4→use bivvy::steps::{
  5→    execute_step, run_check, CheckResult, ExecutionOptions, ResolvedStep, StepResult, StepStatus,
  6→};
  7→use std::collections::HashMap;
  8→use std::fs;
  9→use tempfile::TempDir;
 10→
 11→#[test]
 12→fn public_api_accessible() {
 13→    // Verify all public types are accessible
 14→    let _status: StepStatus = StepStatus::Pending;
 15→    let _check_result = CheckResult::complete("test");
 16→    let _options = ExecutionOptions::default();
 17→}
 18→
 19→#[test]
 20→fn full_step_execution_workflow() {
 21→    let temp = TempDir::new().unwrap();
 22→
 23→    // 1. Create step config
 24→    let config = StepConfig {
 25→        command: Some("echo 'setup complete'".to_string()),
 26→        ..Default::default()
 27→    };
 28→
 29→    // 2. Resolve step
 30→    let step = ResolvedStep::from_config("setup", &config, None);
 31→    assert_eq!(step.name, "setup");
 32→    assert_eq!(step.command, "echo 'setup complete'");
 33→
 34→    // 3. Execute step
 35→    let ctx = InterpolationContext::new();
 36→    let options = ExecutionOptions {
 37→        capture_output: true,
 38→        ..Default::default()
 39→    };
 40→
 41→    let result = execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();
 42→
 43→    // 4. Check result
 44→    assert!(result.success);
 45→    assert_eq!(result.status(), StepStatus::Completed);
 46→    assert!(result.output.unwrap().contains("setup complete"));
 47→}
