 69→
 70→    // Create marker file that indicates completion
 71→    fs::write(temp.path().join("installed.marker"), "done").unwrap();
 72→
 73→    // Create step with completed check
 74→    let mut config = StepConfig {
 75→        command: Some("echo 'should not run'".to_string()),
 76→        completed_check: Some(CompletedCheck::FileExists {
 77→            path: "installed.marker".to_string(),
 78→        }),
 79→        ..Default::default()
 80→    };
 81→    config.completed_check = Some(CompletedCheck::FileExists {
 82→        path: "installed.marker".to_string(),
 83→    });
 84→
 85→    let step = ResolvedStep::from_config("install", &config, None);
 86→
 87→    // Execute - should skip
 88→    let ctx = InterpolationContext::new();
 89→    let result = execute_step(
