  1→//! Interactive prompts.
  2→
  3→use console::{measure_text_width, style, Key, Style, Term};
  4→use dialoguer::theme::ColorfulTheme;
  5→use dialoguer::{Confirm, Input, MultiSelect, Select};
  6→
  7→use crate::error::{BivvyError, Result};
  8→
  9→use super::{Prompt, PromptOption, PromptResult, PromptType};
 10→
 11→/// Convert dialoguer errors to BivvyError.
 12→fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
 13→    BivvyError::Io(e.into())
 14→}
 15→
 16→/// Dialoguer theme without the default yellow `?` prefix.
 17→fn prompt_theme() -> ColorfulTheme {
 18→    ColorfulTheme {
 19→        prompt_prefix: style("".to_string()),
 20→        ..ColorfulTheme::default()
 21→    }
 22→}
 23→
 24→/// Prompt the user for input.
 25→pub fn prompt_user(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
 26→    match &prompt.prompt_type {
 27→        PromptType::Confirm => prompt_confirm(prompt, term),
 28→        PromptType::Input => prompt_input(prompt, term),
 29→        PromptType::Select { options } => prompt_select(prompt, options, term),
 30→        PromptType::MultiSelect { options } => prompt_multiselect(prompt, options, term),
 31→    }
 32→}
 33→
 34→fn prompt_confirm(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
 35→    let default = prompt
 36→        .default
 37→        .as_ref()
 38→        .map(|s| s.to_lowercase() == "true" || s == "y" || s == "yes")
 39→        .unwrap_or(true);
 40→
 41→    let result = Confirm::new()
 42→        .with_prompt(&prompt.question)
 43→        .default(default)
 44→        .interact_on(term)
 45→        .map_err(map_dialoguer_err)?;
 46→
 47→    Ok(PromptResult::Bool(result))
 48→}
 49→
 50→fn prompt_input(prompt: &Prompt, term: &Term) -> Result<PromptResult> {
 51→    let input = Input::<String>::new().with_prompt(&prompt.question);
 52→
 53→    let result: String = if let Some(default) = &prompt.default {
 54→        input
 55→            .default(default.clone())
 56→            .interact_on(term)
 57→            .map_err(map_dialoguer_err)?
 58→    } else {
 59→        input.interact_on(term).map_err(map_dialoguer_err)?
 60→    };
 61→
 62→    Ok(PromptResult::String(result))
 63→}
 64→
 65→/// Dialoguer theme for general select prompts with `›`/`·` indicators.
 66→fn select_theme() -> ColorfulTheme {
 67→    ColorfulTheme {
 68→        prompt_prefix: style("".to_string()),
 69→        prompt_suffix: style("".to_string()),
 70→        success_prefix: style("".to_string()),
 71→        success_suffix: style("·".to_string()).for_stderr().dim(),
 72→        active_item_prefix: style("›".to_string()).for_stderr().bold(),
 73→        inactive_item_prefix: style("·".to_string()).for_stderr().dim(),
 74→        active_item_style: Style::new().for_stderr().bold(),
 75→        inactive_item_style: Style::new().for_stderr().dim(),
 76→        values_style: Style::new().for_stderr().bold(),
 77→        ..ColorfulTheme::default()
 78→    }
 79→}
 80→
 81→/// Check if options form a yes/no pair.
 82→fn is_yes_no(options: &[PromptOption]) -> bool {
 83→    options.len() == 2
 84→        && options.iter().any(|o| o.value == "yes")
 85→        && options.iter().any(|o| o.value == "no")
 86→}
 87→
 88→fn prompt_select(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Result<PromptResult> {
 89→    // Use custom yes/no prompt for y/n keyboard shortcut support
 90→    if is_yes_no(options) {
 91→        return prompt_yes_no(prompt, options, term);
 92→    }
 93→
 94→    let labels: Vec<_> = options.iter().map(|o| o.label.as_str()).collect();
 95→
 96→    let default_idx = prompt
 97→        .default
 98→        .as_ref()
 99→        .and_then(|d| options.iter().position(|o| o.value == *d))
100→        .unwrap_or(0);

