 60→/// Options for command execution.
 61→#[derive(Debug, Clone, Default)]
 62→pub struct CommandOptions {
 63→    /// Working directory.
 64→    pub cwd: Option<std::path::PathBuf>,
 65→
 66→    /// Environment variables (merged with system env).
 67→    pub env: HashMap<String, String>,
 68→
 69→    /// Capture stdout (if false, inherits from parent).
 70→    pub capture_stdout: bool,
 71→
 72→    /// Capture stderr (if false, inherits from parent).
 73→    pub capture_stderr: bool,
 74→
 75→    /// Timeout in seconds (None = no timeout).
 76→    pub timeout: Option<u64>,
 77→}
