218→/// Execute a single step.
219→pub fn execute_step(
220→    step: &ResolvedStep,
221→    project_root: &Path,
222→    context: &InterpolationContext,
223→    global_env: &HashMap<String, String>,
224→    options: &ExecutionOptions,
225→    output_callback: Option<OutputCallback>,
226→) -> Result<StepResult> {
227→    // Check if already complete (unless forced)
228→    if !options.force {
229→        if let Some(ref check) = step.completed_check {
230→            let check_result = run_check(check, project_root);
231→            if check_result.complete {
232→                return Ok(StepResult::skipped(&step.name, check_result));
233→            }
234→        }
235→    }
236→
237→    // Check preconditions (never bypassed by --force)
238→    if let Some(ref precondition) = step.precondition {
239→        let check_result = run_check_interpolated(precondition, project_root, context)?;
240→        if !check_result.complete {
241→            return Ok(StepResult::failure(
242→                &step.name,
243→                Duration::ZERO,
244→                format!("Precondition failed: {}", check_result.short_description()),
245→                check_result.details,
246→            ));
247→        }
248→    }
249→
250→    // Dry run mode
251→    if options.dry_run {
252→        let command = resolve_string(&step.command, context)?;
253→        return Ok(StepResult::success(
254→            &step.name,
255→            Duration::ZERO,
256→            None,
257→            Some(format!("Would run: {}", command)),
258→        ));
259→    }
260→
261→    // Build environment
262→    let mut env = global_env.clone();
263→    env.extend(step.env.iter().map(|(k, v)| (k.clone(), v.clone())));
264→
265→    // Resolve command with interpolation
266→    let command = resolve_string(&step.command, context)?;
267→
268→    // Guard against empty commands
269→    if command.trim().is_empty() {
270→        return Err(BivvyError::StepExecutionError {
271→            step: step.name.clone(),
272→            message: "step has no command to execute (command is empty)".to_string(),
273→        });
274→    }
275→
276→    // Execute before hooks
277→    for hook in &step.before {
278→        let hook_cmd = resolve_string(hook, context)?;
279→        execute_hook(&hook_cmd, project_root, &env)?;
280→    }
281→
282→    // Execute main command
283→    let cmd_options = CommandOptions {
284→        cwd: Some(project_root.to_path_buf()),
285→        env: env.clone(),
286→        capture_stdout: options.capture_output || output_callback.is_none(),
287→        capture_stderr: options.capture_output || output_callback.is_none(),
288→        ..Default::default()
289→    };
290→
291→    let result = if let Some(callback) = output_callback {
292→        execute_streaming(&command, &cmd_options, callback)?
293→    } else {
294→        execute(&command, &cmd_options)?
295→    };
296→
297→    if !result.success {
298→        return Ok(StepResult::failure(
299→            &step.name,
300→            result.duration,

300→            result.duration,
301→            format!("Command failed with exit code {:?}", result.exit_code),
302→            Some(result.stderr),
303→        ));
304→    }
305→
306→    // Execute after hooks
307→    for hook in &step.after {
308→        let hook_cmd = resolve_string(hook, context)?;
309→        execute_hook(&hook_cmd, project_root, &env)?;
310→    }
311→
312→    Ok(StepResult::success(
313→        &step.name,
314→        result.duration,
315→        result.exit_code,
316→        if options.capture_output {
317→            Some(result.stdout)
318→        } else {
319→            None
320→        },
321→    ))
322→}
323→
324→fn execute_hook(command: &str, cwd: &Path, env: &HashMap<String, String>) -> Result<()> {
325→    let options = CommandOptions {
326→        cwd: Some(cwd.to_path_buf()),
327→        env: env.clone(),
328→        capture_stdout: true,
329→        capture_stderr: true,
330→        ..Default::default()
331→    };
332→
333→    let result = execute(command, &options)?;
334→
335→    if !result.success {
336→        return Err(BivvyError::StepExecutionError {
337→            step: "hook".to_string(),
338→            message: format!("Hook '{}' failed: {}", command, result.stderr),
339→        });
340→    }
341→
342→    Ok(())
343→}
