//! Step execution engine.
//!
//! Executes resolved steps with proper environment handling,
//! interpolation, and hook execution.

use crate::config::interpolation::{resolve_string, InterpolationContext};
use crate::error::{BivvyError, Result};
use crate::shell::{execute, execute_streaming, CommandOptions, OutputCallback};
use crate::steps::completed_check::{run_check, run_check_interpolated, CheckResult};
use crate::steps::resolved::ResolvedStep;
use std::collections::HashMap;
use std::path::Path;
use std::time::Duration;

/// Status of a step in the workflow.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StepStatus {
    /// Step is waiting to run.
    Pending,

    /// Step is currently executing.
    Running,

    /// Step completed successfully.
    Completed,

    /// Step failed.
    Failed,

    /// Step was skipped (already complete or dependency failed).
    Skipped,
}

impl StepStatus {
    /// Check if this is a terminal state (no more changes expected).
    pub fn is_terminal(&self) -> bool {
        matches!(
            self,
            StepStatus::Completed | StepStatus::Failed | StepStatus::Skipped
        )
    }

    /// Get a display character for this status.
    pub fn display_char(&self) -> char {
        match self {
            StepStatus::Pending => '○',
            StepStatus::Running => '◉',
            StepStatus::Completed => '✓',
            StepStatus::Failed => '✗',
            StepStatus::Skipped => '⊘',
        }
    }
}

impl std::fmt::Display for StepStatus {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let s = match self {
            StepStatus::Pending => "pending",
            StepStatus::Running => "running",
            StepStatus::Completed => "completed",
            StepStatus::Failed => "failed",
            StepStatus::Skipped => "skipped",
        };
        write!(f, "{}", s)
    }
}

/// Result of executing a step.
#[derive(Debug)]
pub struct StepResult {
    /// Step name.
    pub name: String,

    /// Whether the step succeeded.
    pub success: bool,

    /// Execution duration.
    pub duration: Duration,

    /// Exit code (if command was run).
    pub exit_code: Option<i32>,

    /// Whether step was skipped (already complete).
    pub skipped: bool,

    /// Completion check result (if run).
    pub check_result: Option<CheckResult>,

    /// Error message (if failed).
    pub error: Option<String>,

    /// Captured output (if available).
    pub output: Option<String>,

    /// Recovery detail (e.g., "succeeded on retry (attempt 2)", "skipped by user").
    pub recovery_detail: Option<String>,
}

impl StepResult {
    /// Create a skipped result.
    pub fn skipped(name: &str, check_result: CheckResult) -> Self {
        Self {
            name: name.to_string(),
            success: true,
            duration: Duration::ZERO,
            exit_code: None,
            skipped: true,
            check_result: Some(check_result),
            error: None,
            output: None,
            recovery_detail: None,
        }
    }

    /// Create a success result.
    pub fn success(
        name: &str,
        duration: Duration,
        exit_code: Option<i32>,
        output: Option<String>,
    ) -> Self {
        Self {
            name: name.to_string(),
            success: true,
            duration,
            exit_code,
            skipped: false,
            check_result: None,
            error: None,
            output,
            recovery_detail: None,
        }
    }

    /// Create a failure result.
    pub fn failure(name: &str, duration: Duration, error: String, output: Option<String>) -> Self {
        Self {
            name: name.to_string(),
            success: false,
            duration,
            exit_code: None,
            skipped: false,
            check_result: None,
            error: Some(error),
            output,
            recovery_detail: None,
        }
    }

    /// Get the status of this result.
    pub fn status(&self) -> StepStatus {
        if self.skipped {
            StepStatus::Skipped
        } else if self.success {
            StepStatus::Completed
        } else {
            StepStatus::Failed
        }
    }

    /// Generate a summary line for display.
    pub fn summary_line(&self) -> String {
        let status = self.status();
        let duration_str = format_duration(self.duration);

        match status {
            StepStatus::Completed => {
                format!("{} {} ({})", status.display_char(), self.name, duration_str)
            }
            StepStatus::Skipped => {
                let reason = self
                    .check_result
                    .as_ref()
                    .map(|c| c.short_description())
                    .unwrap_or("already complete");
                format!("{} {} ({})", status.display_char(), self.name, reason)
            }
            StepStatus::Failed => {
                let error = self.error.as_deref().unwrap_or("unknown error");
                format!("{} {} - {}", status.display_char(), self.name, error)
            }
            _ => format!("{} {}", status.display_char(), self.name),
        }
    }
}

fn format_duration(duration: Duration) -> String {
    let secs = duration.as_secs();
    let millis = duration.subsec_millis();

    if secs == 0 {
        format!("{}ms", millis)
    } else if secs < 60 {
        format!("{}.{}s", secs, millis / 100)
    } else {
        let mins = secs / 60;
        let secs = secs % 60;
        format!("{}m {}s", mins, secs)
    }
}

/// Options for step execution.
#[derive(Debug, Clone, Default)]
pub struct ExecutionOptions {
    /// Force run even if completed.
    pub force: bool,

    /// Dry run mode (don't actually execute).
    pub dry_run: bool,

    /// Capture output instead of streaming.
    pub capture_output: bool,

    /// Additional secret patterns to mask.
    pub secret_patterns: Vec<String>,
}

/// Execute a single step.
pub fn execute_step(
    step: &ResolvedStep,
    project_root: &Path,
    context: &InterpolationContext,
    global_env: &HashMap<String, String>,
    options: &ExecutionOptions,
    output_callback: Option<OutputCallback>,
) -> Result<StepResult> {
    // Check if already complete (unless forced)
    if !options.force {
        if let Some(ref check) = step.completed_check {
            let check_result = run_check(check, project_root);
            if check_result.complete {
                return Ok(StepResult::skipped(&step.name, check_result));
            }
        }
    }

    // Check preconditions (never bypassed by --force)
    if let Some(ref precondition) = step.precondition {
        let check_result = run_check_interpolated(precondition, project_root, context)?;
        if !check_result.complete {
            return Ok(StepResult::failure(
                &step.name,
                Duration::ZERO,
                format!("Precondition failed: {}", check_result.short_description()),
                check_result.details,
            ));
        }
    }

    // Dry run mode
    if options.dry_run {
        let command = resolve_string(&step.command, context)?;
        return Ok(StepResult::success(
            &step.name,
            Duration::ZERO,
            None,
            Some(format!("Would run: {}", command)),
        ));
    }

    // Build environment
    let mut env = global_env.clone();
    env.extend(step.env.iter().map(|(k, v)| (k.clone(), v.clone())));

    // Resolve command with interpolation
    let command = resolve_string(&step.command, context)?;

    // Guard against empty commands
    if command.trim().is_empty() {
        return Err(BivvyError::StepExecutionError {
            step: step.name.clone(),
            message: "step has no command to execute (command is empty)".to_string(),
        });
    }

    // Execute before hooks
    for hook in &step.before {
        let hook_cmd = resolve_string(hook, context)?;
        execute_hook(&hook_cmd, project_root, &env)?;
    }

    // Execute main command
    let cmd_options = CommandOptions {
        cwd: Some(project_root.to_path_buf()),
        env: env.clone(),
        capture_stdout: options.capture_output || output_callback.is_none(),
        capture_stderr: options.capture_output || output_callback.is_none(),
        ..Default::default()
    };

    let result = if let Some(callback) = output_callback {
        execute_streaming(&command, &cmd_options, callback)?
    } else {
        execute(&command, &cmd_options)?
    };

    if !result.success {
        return Ok(StepResult::failure(
            &step.name,
            result.duration,
            format!("Command failed with exit code {:?}", result.exit_code),
            Some(result.stderr),
        ));
    }

    // Execute after hooks
    for hook in &step.after {
        let hook_cmd = resolve_string(hook, context)?;
        execute_hook(&hook_cmd, project_root, &env)?;
    }

    Ok(StepResult::success(
        &step.name,
        result.duration,
        result.exit_code,
        if options.capture_output {
            Some(result.stdout)
        } else {
            None
        },
    ))
}

fn execute_hook(command: &str, cwd: &Path, env: &HashMap<String, String>) -> Result<()> {
    let options = CommandOptions {
        cwd: Some(cwd.to_path_buf()),
        env: env.clone(),
        capture_stdout: true,
        capture_stderr: true,
        ..Default::default()
    };

    let result = execute(command, &options)?;

    if !result.success {
        return Err(BivvyError::StepExecutionError {
            step: "hook".to_string(),
            message: format!("Hook '{}' failed: {}", command, result.stderr),
        });
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::CompletedCheck;
    use std::fs;
    use tempfile::TempDir;

    fn make_step(command: &str) -> ResolvedStep {
        ResolvedStep {
            name: "test".to_string(),
            title: "Test Step".to_string(),
            description: None,
            command: command.to_string(),
            depends_on: vec![],
            completed_check: None,
            precondition: None,
            skippable: true,
            required: false,
            prompt_if_complete: true,
            allow_failure: false,
            retry: 0,
            env: HashMap::new(),
            watches: vec![],
            before: vec![],
            after: vec![],
            sensitive: false,
            requires_sudo: false,
            requires: vec![],
            only_environments: vec![],
        }
    }

    #[test]
    fn execute_step_runs_command() {
        let temp = TempDir::new().unwrap();
        let step = make_step("echo hello");
        let ctx = InterpolationContext::new();
        let options = ExecutionOptions {
            capture_output: true,
            ..Default::default()
        };

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        assert!(result.success);
        assert!(!result.skipped);
        assert!(result.output.unwrap().contains("hello"));
    }

    #[test]
    fn execute_step_skips_when_complete() {
        let temp = TempDir::new().unwrap();
        fs::write(temp.path().join("done.txt"), "").unwrap();

        let mut step = make_step("echo should not run");
        step.completed_check = Some(CompletedCheck::FileExists {
            path: "done.txt".to_string(),
        });

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions::default();

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        assert!(result.success);
        assert!(result.skipped);
    }

    #[test]
    fn execute_step_runs_when_forced() {
        let temp = TempDir::new().unwrap();
        fs::write(temp.path().join("done.txt"), "").unwrap();

        let mut step = make_step("echo forced");
        step.completed_check = Some(CompletedCheck::FileExists {
            path: "done.txt".to_string(),
        });

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions {
            force: true,
            capture_output: true,
            ..Default::default()
        };

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        assert!(result.success);
        assert!(!result.skipped);
        assert!(result.output.unwrap().contains("forced"));
    }

    #[test]
    fn execute_step_dry_run() {
        let temp = TempDir::new().unwrap();
        let step = make_step("rm -rf /");

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions {
            dry_run: true,
            ..Default::default()
        };

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        assert!(result.success);
        assert!(result.output.unwrap().contains("Would run"));
    }

    #[test]
    fn execute_step_merges_env() {
        let temp = TempDir::new().unwrap();

        let mut step = make_step(if cfg!(windows) {
            "echo %STEP_VAR%"
        } else {
            "echo $STEP_VAR"
        });
        step.env
            .insert("STEP_VAR".to_string(), "step_value".to_string());

        let mut global_env = HashMap::new();
        global_env.insert("GLOBAL_VAR".to_string(), "global_value".to_string());

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions {
            capture_output: true,
            ..Default::default()
        };

        let result = execute_step(&step, temp.path(), &ctx, &global_env, &options, None).unwrap();

        assert!(result.success);
        assert!(result.output.unwrap().contains("step_value"));
    }

    #[test]
    fn execute_step_runs_hooks() {
        let temp = TempDir::new().unwrap();

        let mut step = make_step("echo main");
        step.before = vec!["echo before".to_string()];
        step.after = vec!["echo after".to_string()];

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions {
            capture_output: true,
            ..Default::default()
        };

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();
        assert!(result.success);
    }

    #[test]
    fn execute_step_fails_on_hook_failure() {
        let temp = TempDir::new().unwrap();

        let mut step = make_step("echo main");
        step.before = vec!["exit 1".to_string()];

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions::default();

        let result = execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None);
        assert!(result.is_err());
    }

    #[test]
    fn hooks_execute_in_order() {
        let temp = TempDir::new().unwrap();
        let order_file = temp.path().join("order.txt");

        let mut step = make_step(&format!("echo main >> {}", order_file.display()));
        step.before = vec![
            format!("echo before1 >> {}", order_file.display()),
            format!("echo before2 >> {}", order_file.display()),
        ];
        step.after = vec![format!("echo after1 >> {}", order_file.display())];

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions::default();

        execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        let content = fs::read_to_string(&order_file).unwrap();
        let lines: Vec<_> = content.lines().map(|l| l.trim()).collect();

        assert_eq!(lines, vec!["before1", "before2", "main", "after1"]);
    }

    #[test]
    fn before_hook_failure_stops_execution() {
        let temp = TempDir::new().unwrap();
        let marker = temp.path().join("ran.txt");

        let mut step = make_step(&format!("touch {}", marker.display()));
        step.before = vec!["exit 1".to_string()];

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions::default();

        let result = execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None);

        assert!(result.is_err());
        assert!(!marker.exists());
    }

    #[test]
    fn after_hooks_skipped_on_command_failure() {
        let temp = TempDir::new().unwrap();
        let marker = temp.path().join("after-ran.txt");

        let mut step = make_step("exit 1");
        step.after = vec![format!("touch {}", marker.display())];

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions::default();

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        assert!(!result.success);
        assert!(!marker.exists());
    }

    #[test]
    #[cfg(unix)]
    fn hooks_receive_step_env() {
        let temp = TempDir::new().unwrap();
        let output_file = temp.path().join("env.txt");

        let mut step = make_step("echo done");
        step.env
            .insert("HOOK_VAR".to_string(), "hook_value".to_string());
        step.before = vec![format!("echo $HOOK_VAR >> {}", output_file.display())];

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions::default();

        execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        let content = fs::read_to_string(&output_file).unwrap();
        assert!(content.contains("hook_value"));
    }

    #[test]
    fn execute_step_rejects_empty_command() {
        let temp = TempDir::new().unwrap();
        let step = make_step("");
        let ctx = InterpolationContext::new();
        let options = ExecutionOptions::default();

        let result = execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None);

        assert!(result.is_err());
        let err = result.unwrap_err();
        assert!(err.to_string().contains("empty"), "error was: {}", err);
    }

    #[test]
    fn execute_step_rejects_whitespace_only_command() {
        let temp = TempDir::new().unwrap();
        let step = make_step("   ");
        let ctx = InterpolationContext::new();
        let options = ExecutionOptions::default();

        let result = execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None);

        assert!(result.is_err());
        let err = result.unwrap_err();
        assert!(err.to_string().contains("empty"), "error was: {}", err);
    }

    #[test]
    fn step_status_is_terminal() {
        assert!(!StepStatus::Pending.is_terminal());
        assert!(!StepStatus::Running.is_terminal());
        assert!(StepStatus::Completed.is_terminal());
        assert!(StepStatus::Failed.is_terminal());
        assert!(StepStatus::Skipped.is_terminal());
    }

    #[test]
    fn step_status_display_char() {
        assert_eq!(StepStatus::Completed.display_char(), '✓');
        assert_eq!(StepStatus::Failed.display_char(), '✗');
        assert_eq!(StepStatus::Skipped.display_char(), '⊘');
    }

    #[test]
    fn step_status_display() {
        assert_eq!(format!("{}", StepStatus::Pending), "pending");
        assert_eq!(format!("{}", StepStatus::Completed), "completed");
    }

    #[test]
    fn step_result_status() {
        let result = StepResult::success("test", Duration::from_secs(1), Some(0), None);
        assert_eq!(result.status(), StepStatus::Completed);

        let result = StepResult::failure("test", Duration::from_secs(1), "error".to_string(), None);
        assert_eq!(result.status(), StepStatus::Failed);

        let check_result = crate::steps::CheckResult::complete("already done");
        let result = StepResult::skipped("test", check_result);
        assert_eq!(result.status(), StepStatus::Skipped);
    }

    #[test]
    fn step_result_summary_line_includes_status() {
        let result = StepResult::success("test", Duration::from_secs(1), Some(0), None);
        let line = result.summary_line();
        assert!(line.contains('✓'));
        assert!(line.contains("test"));
    }

    #[test]
    fn step_result_summary_line_skipped_shows_check_description() {
        let check_result =
            crate::steps::CheckResult::complete("Command succeeded: rustc --version");
        let result = StepResult::skipped("rust", check_result);
        let line = result.summary_line();
        assert!(line.contains("rustc --version"), "got: {}", line);
        assert!(!line.contains("already complete"), "got: {}", line);
    }

    #[test]
    fn step_result_summary_line_skipped_without_check_result() {
        let mut result =
            StepResult::skipped("test", crate::steps::CheckResult::complete("User declined"));
        result.check_result = None;
        let line = result.summary_line();
        assert!(line.contains("already complete"), "got: {}", line);
    }

    #[test]
    fn step_result_recovery_detail_defaults_none() {
        let success = StepResult::success("test", Duration::from_secs(1), Some(0), None);
        assert!(success.recovery_detail.is_none());

        let failure =
            StepResult::failure("test", Duration::from_secs(1), "error".to_string(), None);
        assert!(failure.recovery_detail.is_none());

        let check_result = crate::steps::CheckResult::complete("done");
        let skipped = StepResult::skipped("test", check_result);
        assert!(skipped.recovery_detail.is_none());
    }

    // --- Precondition tests ---

    #[test]
    fn precondition_passes_allows_execution() {
        let temp = TempDir::new().unwrap();
        let mut step = make_step("echo hello");
        step.precondition = Some(CompletedCheck::CommandSucceeds {
            command: "exit 0".to_string(),
        });

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions {
            capture_output: true,
            ..Default::default()
        };

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        assert!(result.success);
        assert!(!result.skipped);
    }

    #[test]
    fn precondition_fails_returns_failure() {
        let temp = TempDir::new().unwrap();
        let mut step = make_step("echo should not run");
        step.precondition = Some(CompletedCheck::CommandSucceeds {
            command: "exit 1".to_string(),
        });

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions::default();

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        assert!(!result.success);
        assert!(result
            .error
            .as_ref()
            .unwrap()
            .contains("Precondition failed"));
    }

    #[test]
    fn precondition_not_bypassed_by_force() {
        let temp = TempDir::new().unwrap();
        let mut step = make_step("echo should not run");
        step.precondition = Some(CompletedCheck::CommandSucceeds {
            command: "exit 1".to_string(),
        });

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions {
            force: true,
            ..Default::default()
        };

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        assert!(
            !result.success,
            "precondition should not be bypassed by force"
        );
    }

    #[test]
    fn precondition_evaluated_after_completed_check() {
        let temp = TempDir::new().unwrap();
        fs::write(temp.path().join("done.txt"), "").unwrap();

        let mut step = make_step("echo should not run");
        // completed_check passes → should skip; precondition would fail
        step.completed_check = Some(CompletedCheck::FileExists {
            path: "done.txt".to_string(),
        });
        step.precondition = Some(CompletedCheck::CommandSucceeds {
            command: "exit 1".to_string(),
        });

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions::default();

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        // completed_check causes skip, precondition never evaluated
        assert!(result.success);
        assert!(result.skipped);
    }

    #[test]
    fn precondition_failure_message_includes_description() {
        let temp = TempDir::new().unwrap();
        let mut step = make_step("echo test");
        step.precondition = Some(CompletedCheck::CommandSucceeds {
            command: "exit 1".to_string(),
        });

        let ctx = InterpolationContext::new();
        let options = ExecutionOptions::default();

        let result =
            execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

        let error = result.error.as_ref().unwrap();
        assert!(
            error.contains("Precondition failed"),
            "error should mention precondition: {}",
            error
        );
    }

    #[test]
    fn format_duration_formats_correctly() {
        assert_eq!(format_duration(Duration::from_millis(500)), "500ms");
        assert_eq!(format_duration(Duration::from_secs(5)), "5.0s");
        assert_eq!(format_duration(Duration::from_secs(65)), "1m 5s");
    }
}

//! CLI argument definitions.
//!
//! This module defines all CLI arguments using clap's derive macros.
//! The main entry point is the [`Cli`] struct.

use clap::{Parser, Subcommand};
use clap_complete::Shell;
use std::path::PathBuf;

/// Bivvy - Development environment setup automation.
#[derive(Debug, Parser)]
#[command(name = "bivvy")]
#[command(author, version, about, long_about = None)]
#[command(propagate_version = true)]
pub struct Cli {
    /// Path to config file (overrides default .bivvy/config.yml)
    #[arg(short, long, global = true)]
    pub config: Option<PathBuf>,

    /// Path to project root (overrides current directory)
    #[arg(short, long, global = true)]
    pub project: Option<PathBuf>,

    /// Show verbose output
    #[arg(short, long, global = true)]
    pub verbose: bool,

    /// Minimal output
    #[arg(short, long, global = true)]
    pub quiet: bool,

    /// Disable colored output
    #[arg(long, global = true)]
    pub no_color: bool,

    /// Enable debug logging
    #[arg(long, global = true)]
    pub debug: bool,

    #[command(subcommand)]
    pub command: Option<Commands>,
}

use super::commands::cache::CacheArgs;
use super::commands::feedback::FeedbackArgs;

/// Available subcommands.
#[derive(Debug, Subcommand)]
pub enum Commands {
    /// Run setup workflow (default if no command specified)
    Run(RunArgs),

    /// Initialize Bivvy configuration for a project
    Init(InitArgs),

    /// Show current setup status
    Status(StatusArgs),

    /// List available steps and workflows
    List(ListArgs),

    /// Show last run information
    Last(LastArgs),

    /// Show execution history
    History(HistoryArgs),

    /// Validate configuration files
    Lint(LintArgs),

    /// Show resolved configuration
    Config(ConfigArgs),

    /// Manage template cache
    Cache(CacheArgs),

    /// Capture and manage feedback
    Feedback(FeedbackArgs),

    /// Generate shell completions
    Completions(CompletionsArgs),
}

/// Arguments for the `run` command.
#[derive(Debug, Clone, clap::Args)]
pub struct RunArgs {
    /// Workflow to run
    #[arg(short, long, default_value = "default")]
    pub workflow: String,

    /// Run only specified steps (comma-separated)
    #[arg(long, value_delimiter = ',')]
    pub only: Vec<String>,

    /// Skip specified steps (comma-separated)
    #[arg(long, value_delimiter = ',')]
    pub skip: Vec<String>,

    /// How to handle skipped step dependencies
    #[arg(long, default_value = "skip_with_dependents")]
    pub skip_behavior: String,

    /// Force re-run of specified steps (comma-separated)
    #[arg(short, long, value_delimiter = ',')]
    pub force: Vec<String>,

    /// Resume an interrupted run
    #[arg(long)]
    pub resume: bool,

    /// Save prompt answers for future runs
    #[arg(long)]
    pub save_preferences: bool,

    /// Preview commands without executing
    #[arg(long)]
    pub dry_run: bool,

    /// Use defaults, no prompts
    #[arg(long)]
    pub non_interactive: bool,

    /// Deprecated: use --non-interactive and --env ci instead
    #[arg(long, hide = true)]
    pub ci: bool,

    /// Target environment (e.g., development, ci, staging)
    #[arg(long, value_name = "ENV")]
    pub env: Option<String>,
}

impl Default for RunArgs {
    fn default() -> Self {
        Self {
            workflow: "default".to_string(),
            only: Vec::new(),
            skip: Vec::new(),
            skip_behavior: "skip_with_dependents".to_string(),
            force: Vec::new(),
            resume: false,
            save_preferences: false,
            dry_run: false,
            non_interactive: false,
            ci: false,
            env: None,
        }
    }
}

/// Arguments for the `init` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct InitArgs {
    /// Generate minimal config without prompts
    #[arg(long)]
    pub minimal: bool,

    /// Start from a specific template
    #[arg(long)]
    pub template: Option<String>,

    /// Copy configuration from another project
    #[arg(long)]
    pub from: Option<String>,

    /// Overwrite existing configuration
    #[arg(long)]
    pub force: bool,
}

/// Arguments for the `status` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct StatusArgs {
    /// Output as JSON
    #[arg(long)]
    pub json: bool,

    /// Show status for specific step
    #[arg(long)]
    pub step: Option<String>,

    /// Target environment (e.g., development, ci, staging)
    #[arg(long, value_name = "ENV")]
    pub env: Option<String>,
}

/// Arguments for the `list` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct ListArgs {
    /// List only steps
    #[arg(long)]
    pub steps_only: bool,

    /// List only workflows
    #[arg(long)]
    pub workflows_only: bool,

    /// Output as JSON
    #[arg(long)]
    pub json: bool,

    /// Target environment (e.g., development, ci, staging)
    #[arg(long, value_name = "ENV")]
    pub env: Option<String>,
}

/// Arguments for the `last` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct LastArgs {
    /// Output as JSON
    #[arg(long)]
    pub json: bool,

    /// Show details for specific step
    #[arg(long)]
    pub step: Option<String>,

    /// Show all runs
    #[arg(long)]
    pub all: bool,

    /// Include command output
    #[arg(long)]
    pub output: bool,
}

/// Arguments for the `history` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct HistoryArgs {
    /// Filter by step name
    #[arg(long)]
    pub step: Option<String>,

    /// Number of runs to show
    #[arg(long)]
    pub limit: Option<usize>,

    /// Show runs since duration (e.g., "1h", "7d", "30m")
    #[arg(long)]
    pub since: Option<String>,

    /// Show detailed view with steps for each run
    #[arg(long)]
    pub detail: bool,

    /// Output as JSON
    #[arg(long)]
    pub json: bool,
}

/// Arguments for the `lint` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct LintArgs {
    /// Output format: human, json, sarif
    #[arg(long, default_value = "human")]
    pub format: String,

    /// Auto-fix simple issues
    #[arg(long)]
    pub fix: bool,

    /// Treat warnings as errors
    #[arg(long)]
    pub strict: bool,
}

/// Arguments for the `config` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct ConfigArgs {
    /// Output as JSON
    #[arg(long)]
    pub json: bool,

    /// Output as YAML
    #[arg(long)]
    pub yaml: bool,

    /// Show fully merged config
    #[arg(long)]
    pub merged: bool,
}

/// Arguments for the `completions` command.
#[derive(Debug, Clone, clap::Args)]
pub struct CompletionsArgs {
    /// Shell to generate completions for
    #[arg(value_enum)]
    pub shell: Shell,
}

