//! Run command implementation.
//!
//! The `bivvy run` command executes setup workflows.

use std::collections::{HashMap, HashSet};
use std::path::{Path, PathBuf};

use crate::cli::args::RunArgs;
use crate::config::{evaluate_vars, load_merged_config, ConfigPaths, InterpolationContext};
use crate::environment::resolver::ResolvedEnvironment;
use crate::error::{BivvyError, Result};
use crate::registry::Registry;
use crate::requirements::checker::GapChecker;
use crate::requirements::probe::EnvironmentProbe;
use crate::requirements::registry::RequirementRegistry;
use crate::runner::{RunOptions, SkipBehavior, WorkflowRunner};
use crate::state::{ProjectId, RunHistoryBuilder, StateStore};
use crate::steps::ResolvedStep;
use crate::ui::{hints, OutputMode, RunSummary, StatusKind, StepSummary, UserInterface};

use super::dispatcher::{Command, CommandResult};

/// The run command implementation.
pub struct RunCommand {
    project_root: PathBuf,
    args: RunArgs,
}

impl RunCommand {
    /// Create a new run command.
    pub fn new(project_root: &Path, args: RunArgs) -> Self {
        Self {
            project_root: project_root.to_path_buf(),
            args,
        }
    }

    /// Get the project root path.
    pub fn project_root(&self) -> &Path {
        &self.project_root
    }

    /// Get the command arguments.
    pub fn args(&self) -> &RunArgs {
        &self.args
    }

    /// Build run options from args.
    fn build_options(&self) -> RunOptions {
        let skip_behavior = match self.args.skip_behavior.as_str() {
            "skip_only" => SkipBehavior::SkipOnly,
            "run_anyway" => SkipBehavior::RunAnyway,
            _ => SkipBehavior::SkipWithDependents,
        };

        RunOptions {
            workflow: Some(self.args.workflow.clone()),
            only: self.args.only.iter().cloned().collect(),
            skip: self.args.skip.iter().cloned().collect(),
            skip_behavior,
            force: self.args.force.iter().cloned().collect(),
            dry_run: self.args.dry_run,
            provided_requirements: HashSet::new(),
            active_environment: None,
        }
    }

    /// Resolve the target environment using the priority chain.
    fn resolve_environment(&self, config: &crate::config::BivvyConfig) -> ResolvedEnvironment {
        ResolvedEnvironment::resolve_from_config(self.args.env.as_deref(), &config.settings)
    }

    /// Resolve steps from configuration.
    ///
    /// Steps with a `template` field are resolved through the Registry,
    /// which merges template defaults with config overrides. Steps without
    /// a template are treated as inline definitions.
    fn resolve_steps(
        &self,
        config: &crate::config::BivvyConfig,
        environment: Option<&str>,
    ) -> Result<HashMap<String, ResolvedStep>> {
        let registry = if config.template_sources.is_empty() {
            Registry::new(Some(&self.project_root))?
        } else {
            Registry::with_remote_sources(Some(&self.project_root), &config.template_sources)?
        };

        let mut steps = HashMap::new();
        for (name, step_config) in &config.steps {
            let resolved = if let Some(template_name) = &step_config.template {
                let (template, _source) = registry.resolve(template_name)?;
                ResolvedStep::from_template(
                    name,
                    template,
                    step_config,
                    &step_config.inputs,
                    environment,
                )
            } else {

content.content:
 100→            } else {
 101→                ResolvedStep::from_config(name, step_config, environment)
 102→            };
 103→            steps.insert(name.clone(), resolved);
 104→        }
 105→        Ok(steps)
 106→    }
 107→}
 108→
 109→impl Command for RunCommand {
 110→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 111→        // Load configuration
 112→        let config = match load_merged_config(&self.project_root) {
 113→            Ok(c) => c,
 114→            Err(BivvyError::ConfigNotFound { .. }) => {
 115→                ui.error("No configuration found. Run 'bivvy init' first.");
 116→                return Ok(CommandResult::failure(2));
 117→            }
 118→            Err(e) => return Err(e),
 119→        };
 120→
 121→        // Deprecation warning for --ci flag
 122→        if self.args.ci {
 123→            ui.warning(
 124→                "--ci is deprecated and will be removed in 2.0. \
 125→                 Use --non-interactive and --env ci instead.",
 126→            );
 127→        }
 128→
 129→        // Apply config default_output when no CLI flag was explicitly set.
 130→        // OutputMode::Normal means the user didn't pass --verbose or --quiet.
 131→        if ui.output_mode() == OutputMode::Normal {
 132→            ui.set_output_mode(config.settings.default_output.into());
 133→        }
 134→
 135→        // Resolve environment (before header so we can use resolved workflow)
 136→        let resolved_env = self.resolve_environment(&config);
 137→        let env_name = resolved_env.name.clone();
 138→
 139→        // Warn if the environment is not known
 140→        if !resolved_env.is_known(&config) {
 141→            ui.warning(&format!(
 142→                "Unknown environment '{}'. It is not defined in settings.environments                  or a built-in. Step overrides for this environment will have no effect.",
 143→                env_name
 144→            ));
 145→        }
 146→
 147→        // Get provided_requirements from environment config
 148→        let provided_requirements: HashSet<String> = config
 149→            .settings
 150→            .environments
 151→            .get(&env_name)
 152→            .map(|env_config| env_config.provided_requirements.iter().cloned().collect())
 153→            .unwrap_or_default();
 154→
 155→        // Use environment's default_workflow if no explicit --workflow and config has one
 156→        let workflow_name = if self.args.workflow == "default" {
 157→            config
 158→                .settings
 159→                .environments
 160→                .get(&env_name)
 161→                .and_then(|env_config| env_config.default_workflow.clone())
 162→                .unwrap_or_else(|| self.args.workflow.clone())
 163→        } else {
 164→            self.args.workflow.clone()
 165→        };
 166→
 167→        // Show header
 168→        let app_name = config.app_name.as_deref().unwrap_or("project");
 169→        let step_count = config
 170→            .workflows
 171→            .get(workflow_name.as_str())
 172→            .map(|w| w.steps.len())
 173→            .unwrap_or(0);
 174→        ui.show_run_header(
 175→            app_name,
 176→            &workflow_name,
 177→            step_count,
 178→            crate::updates::version::VERSION,
 179→        );
 180→
 181→        // Show environment and config info
 182→        ui.message(&format!(
 183→            "  Environment: {} ({})",
 184→            env_name, resolved_env.source
 185→        ));
 186→
 187→        if self.args.dry_run {
 188→            let paths = ConfigPaths::discover(&self.project_root);
 189→            if let Some(project_path) = &paths.project {
 190→                ui.message(&format!("Config: {}", project_path.display()));
 191→            }
 192→        }
 193→
 194→        // Check for dry-run mode
 195→        if self.args.dry_run {
 196→            ui.message("Running in dry-run mode - no commands will be executed");
 197→        }
 198→
 199→        // Get project identity
 200→        let project_id = ProjectId::from_path(&self.project_root)?;
 201→
 202→        // Load state
 203→        let mut state = StateStore::load(&project_id)?;
 204→
 205→        // Resolve steps with environment
 206→        let steps = self.resolve_steps(&config, Some(&env_name))?;
 207→
 208→        // Check if workflow exists
 209→        if !config.workflows.contains_key(&workflow_name) {
 210→            ui.error(&format!("Unknown workflow: {}", workflow_name));
 211→            return Ok(CommandResult::failure(1));
 212→        }
 213→
 214→        // Extract workflow-level non_interactive setting
 215→        let workflow_non_interactive = config
 216→            .workflows
 217→            .get(&workflow_name)
 218→            .and_then(|w| w.settings.as_ref())
 219→            .is_some_and(|s| s.non_interactive);
 220→
 221→        // Extract step overrides from workflow config
 222→        let step_overrides = config
 223→            .workflows
 224→            .get(&workflow_name)
 225→            .map(|w| w.overrides.clone())
 226→            .unwrap_or_default();
 227→
 228→        // Build run options with resolved workflow and provided requirements
 229→        let mut options = self.build_options();
 230→        options.workflow = Some(workflow_name.clone());
 231→        options.provided_requirements = provided_requirements;
 232→        options.active_environment = Some(env_name.clone());
 233→
 234→        // Create runner
 235→        let runner = WorkflowRunner::new(&config, steps);
 236→
 237→        // Create gap checker for requirement detection
 238→        let probe = EnvironmentProbe::run();
 239→        let req_registry = RequirementRegistry::new().with_custom(&config.requirements);
 240→        let mut gap_checker = GapChecker::new(&req_registry, &probe, &self.project_root);
 241→
 242→        // Evaluate user-defined vars
 243→        let resolved_vars = evaluate_vars(&config.vars, &self.project_root)?;
 244→
 245→        // Create interpolation context
 246→        let ctx = InterpolationContext::new().with_vars(resolved_vars);
 247→        let global_env: HashMap<String, String> = std::env::vars().collect();
 248→
 249→        // Start history recording
 250→        let mut history = RunHistoryBuilder::start(&workflow_name);
 251→
 252→        // Run the workflow with UI-driven interactive prompts
 253→        let result = runner.run_with_ui(
 254→            &options,
 255→            &ctx,
 256→            &global_env,
 257→            &self.project_root,
 258→            workflow_non_interactive,
 259→            &step_overrides,
 260→            Some(&mut gap_checker),
 261→            ui,
 262→        )?;
 263→
 264→        // Record step results to history
 265→        for step_result in &result.steps {
 266→            history.step_run(&step_result.name);
 267→        }
 268→        for skipped in &result.skipped {
 269→            history.step_skipped(skipped);
 270→        }
 271→
 272→        // Update state (unless dry-run)
 273→        if !self.args.dry_run {
 274→            let record = if result.success {
 275→                history.finish_success()
 276→            } else {
 277→                history.finish_failed("One or more steps failed")
 278→            };
 279→            state.record_run(record);
 280→            state.save(&project_id)?;
 281→        }
 282→
 283→        // Build and show run summary
 284→        let steps_run = result.steps.len();
 285→        let steps_skipped = result.skipped.len();
 286→        let failed_steps: Vec<String> = result
 287→            .steps
 288→            .iter()
 289→            .filter(|s| !s.success && !s.skipped)
 290→            .map(|s| s.name.clone())
 291→            .collect();
 292→
 293→        let step_results: Vec<StepSummary> = result
 294→            .steps
 295→            .iter()
 296→            .map(|s| StepSummary {
 297→                name: s.name.clone(),
 298→                status: StatusKind::from(s.status()),
 299→                duration: if s.duration.as_millis() > 0 {
 300→                    Some(s.duration)
 301→                } else {
 302→                    None
 303→                },
 304→                detail: if let Some(ref rd) = s.recovery_detail {
 305→                    Some(rd.clone())
 306→                } else if s.skipped {
 307→                    Some(
 308→                        s.check_result
 309→                            .as_ref()
 310→                            .map(|c| c.short_description().to_string())
 311→                            .unwrap_or_else(|| "already complete".to_string()),
 312→                    )
 313→                } else if !s.success && !s.skipped {
 314→                    s.error.clone()
 315→                } else {
 316→                    None
 317→                },
 318→            })
 319→            .collect();
 320→
 321→        let summary = RunSummary {
 322→            step_results,
 323→            total_duration: result.duration,
 324→            steps_run,
 325→            steps_skipped,
 326→            success: result.success,
 327→            failed_steps: failed_steps.clone(),
 328→        };
 329→
 330→        ui.show_run_summary(&summary);
 331→
 332→        // Show contextual hint
 333→        if result.success {
 334→            ui.show_hint(hints::after_successful_run());
 335→            Ok(CommandResult::success())
 336→        } else if result.aborted {
 337→            ui.show_hint("Workflow aborted by user. Re-run to resume.");
 338→            Ok(CommandResult::failure(1))
 339→        } else {
 340→            ui.show_hint(&hints::after_failed_run(&failed_steps));
 341→            Ok(CommandResult::failure(1))
 342→        }
 343→    }
 344→}
